using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Description = "Start your day right with hearty morning meals", Icon = "🍳" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday recipes", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Impressive dishes for evening dining", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🥨" },
            new() { Name = "Drinks", Description = "Refreshing beverages and cocktails", Icon = "🥤" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt\nButter for cooking",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a buttered pan over medium heat.\n5. Pour 1/4 cup batter per pancake.\n6. Flip when bubbles form on surface.\n7. Cook until golden brown on both sides.",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Dinner",
                Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n100g Pecorino Romano\n2 cloves garlic\nBlack pepper\nSalt",
                Steps = "1. Cook spaghetti in salted boiling water.\n2. Fry pancetta until crispy.\n3. Mix egg yolks with grated cheese and pepper.\n4. Drain pasta, reserving some water.\n5. Toss hot pasta with pancetta off heat.\n6. Quickly stir in egg mixture.\n7. Add pasta water to reach creamy consistency.",
                AverageRating = 4.8, RatingCount = 24
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup Parmesan\nCaesar dressing\nLemon juice\nAnchovy fillets (optional)",
                Steps = "1. Wash and chop romaine lettuce.\n2. Make dressing: blend garlic, anchovy, lemon, and oil.\n3. Toss lettuce with dressing.\n4. Top with croutons and shaved Parmesan.\n5. Season with fresh black pepper.",
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n100g butter\n3 eggs\n100g sugar\n50g flour\nPinch of salt\nButter for ramekins",
                Steps = "1. Preheat oven to 220°C (425°F).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until fluffy.\n4. Fold chocolate mixture into eggs.\n5. Gently fold in flour and salt.\n6. Pour into buttered ramekins.\n7. Bake 12 minutes until edges set but center is soft.\n8. Invert onto plates and serve immediately.",
                AverageRating = 4.9, RatingCount = 31
            },
            new()
            {
                Id = 5, Title = "Guacamole", Category = "Snacks",
                Ingredients = "3 ripe avocados\n1 lime\n1/2 red onion\n2 tomatoes\nFresh cilantro\n1 jalapeño\nSalt and pepper",
                Steps = "1. Halve avocados and remove pits.\n2. Mash avocado to desired consistency.\n3. Dice onion, tomatoes, and jalapeño.\n4. Chop cilantro.\n5. Mix all ingredients together.\n6. Squeeze lime juice over top.\n7. Season with salt and pepper.\n8. Serve with tortilla chips.",
                AverageRating = 4.6, RatingCount = 18
            },
            new()
            {
                Id = 6, Title = "Iced Matcha Latte", Category = "Drinks",
                Ingredients = "2 tsp matcha powder\n2 tbsp hot water\n1 cup milk\nIce cubes\n1 tsp honey (optional)",
                Steps = "1. Sift matcha powder into a bowl.\n2. Add hot water and whisk until smooth.\n3. Fill a glass with ice cubes.\n4. Pour milk over ice.\n5. Pour matcha over the milk.\n6. Stir or layer as desired.\n7. Add honey if sweetness is preferred.",
                AverageRating = 4.3, RatingCount = 15
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

