                AverageRating = 4.6, RatingCount = 18
            },
            new()
            {
                Id = 6, Title = "Iced Matcha Latte", Category = "Drinks",
                Ingredients = "2 tsp matcha powder\n2 tbsp hot water\n1 cup milk\nIce cubes\n1 tsp honey (optional)",
                Steps = "1. Sift matcha powder into a bowl.\n2. Add hot water and whisk until smooth.\n3. Fill a glass with ice cubes.\n4. Pour milk over ice.\n5. Pour matcha over the milk.\n6. Stir or layer as desired.\n7. Add honey if sweetness is preferred.",
                AverageRating = 4.3, RatingCount = 15
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

