@using RecipeCommunity.Models

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container my-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit Your Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (SubmitSuccess)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@Submission.Title</strong>" has been added to the @Submission.Category category.</p>
            <a href="/recipes/@Submission.Category.ToLower()" class="btn btn-primary">View Category</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="ResetForm">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="@Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="@(() => Submission.Title)" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="@(() => Submission.Category)" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Submission.Ingredients"
                    placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                <ValidationMessage For="@(() => Submission.Ingredients)" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="8" @bind-Value="Submission.Steps"
                    placeholder="Write each step on a new line&#10;e.g.,&#10;1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
                <ValidationMessage For="@(() => Submission.Steps)" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    [Inject] public RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeSubmission Submission { get; set; } = new();
    private bool SubmitSuccess { get; set; }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(Submission);
        SubmitSuccess = true;
    }

    private void ResetForm()
    {
        Submission = new RecipeSubmission();
        SubmitSuccess = false;
    }
}

